let colorGame=null,colorAnswers=[],extraGeneration=0;
function recordPageView(){if(window.hfAuth?.user&&hfAuth.user.role!=='admin'&&hfAuth.user.employee!=='1111')api('/api/page-view',{route:location.hash.slice(1)}).catch(()=>{});}
function extraDialog(title,body){let d=document.querySelector('#extra-dialog');if(!d){d=document.createElement('dialog');d.id='extra-dialog';d.className='progress-dialog';document.body.append(d);}d.innerHTML=`<div class="progress-dialog-head"><h2>${esc(title)}</h2><button type="button" class="dialog-close-icon" aria-label="닫기">×</button></div>${body}`;d.querySelector('.dialog-close-icon').onclick=()=>d.close();d.showModal();return d;}
async function renderExtras(route,target){const generation=++extraGeneration;target.innerHTML=`<h1 class="view-title">${esc(titles[route])}</h1><p class="muted">불러오는 중…</p>`;try{
 if(route==='study'){target.innerHTML='<h1 class="view-title">같이 공부할래?</h1>';renderSharedStudys(target);return;}
 if(route==='jobs'){const d=await api('/api/jobs');if(generation!==extraGeneration||location.hash!=='#jobs')return;target.innerHTML=`<h1 class="view-title">오늘의 채용 소식</h1><section class="panel"><div class="extra-actions"><h2>링커리어 공개 채용 공고</h2><a class="auth-link" href="https://linkareer.com/recruit-home" target="_blank" rel="noopener">링커리어 전체 보기 ↗</a><a class="auth-link" href="https://jasoseol.com" target="_blank" rel="noopener">자소설닷컴 ↗</a></div><p class="muted">${esc(d.message||'공개 공고 목록 · 1시간마다 갱신')}</p>${d.jobs.map(j=>`<a class="wiki-title-row" target="_blank" rel="noopener" href="${esc(j.link)}"><span>${esc(j.title)}</span><span>↗</span></a>`).join('')||'<p>현재 공고 목록을 불러올 수 없습니다. 위 채용 사이트에서 확인해 주세요.</p>'}</section>`;return;}
 if(route==='analytics'){const d=await api('/api/analytics');if(location.hash!=='#analytics')return;target.innerHTML=`<h1 class="view-title">일반 회원 이용 통계</h1><p class="muted">최근 30일 · 기능 적용 시점부터 집계 · 관리자와 테스트 계정 제외 · 같은 페이지는 30초 내 중복 집계하지 않습니다.</p><section class="panel"><div class="analytics-row"><strong>페이지</strong><strong>방문 수</strong><strong>이용자 수</strong></div>${d.rows.map(r=>`<div class="analytics-row"><span>${esc(titles[r.route]||r.route)}</span><span>${r.views}</span><span>${r.visitors}</span></div>`).join('')||'<p>아직 집계된 일반 회원 방문이 없습니다.</p>'}</section>`;return;}
 if(route==='stroop'){const d=await api('/api/stroop');if(location.hash!=='#stroop')return;target.innerHTML=`<h1 class="view-title">색깔 맞추기</h1><section class="panel"><p>글자가 뜻하는 색이 아니라 <strong>실제 글자 색</strong>을 고르세요. 10문제의 정확도와 소요 시간으로 순위를 정합니다.</p><div id="color-play"><div class="stroop-word" style="color:#ce3e45">파랑</div><p class="muted">위 예시의 정답은 빨강!</p><button class="primary" id="color-start">시작하기</button></div></section><section class="panel"><h2>이번 주 랭킹</h2>${d.scores.map((r,i)=>`<div class="row ranking-row ${i<3?'rank-podium rank-'+(i+1):''}"><strong class="rank-number">${i+1}</strong><span>${esc(r.name)}</span><small>${r.correct}/10 · ${(r.elapsed/1000).toFixed(1)}초</small></div>`).join('')||'<p class="muted">첫 기록에 도전해 보세요.</p>'}</section>`;return;}
 if(route==='anonymous'){const d=await api('/api/anonymous');if(location.hash!=='#anonymous')return;const admin=hfAuth.user.role==='admin';target.innerHTML=`<h1 class="view-title">익명 게시판</h1><div class="extra-actions"><p class="muted">승인된 회원끼리 익명으로 이야기해요. 글과 댓글에는 계정 정보가 표시되지 않습니다.</p><button class="primary" id="anonymous-compose">익명 글 쓰기</button></div>${d.posts.map(p=>`<article class="panel anonymous-card"><small class="muted">익명 · ${esc(p.created.slice(0,16).replace('T',' '))}</small><h2>${esc(p.title)}</h2><p>${esc(p.body)}</p><div class="extra-actions"><button class="auth-link" data-anon-action="heart" data-id="${p.id}" aria-pressed="${p.liked}">${p.liked?'♥':'♡'} ${p.hearts}</button><button class="auth-link" data-anon-action="report" data-id="${p.id}">신고</button>${p.owned||admin?`<button class="auth-link" data-anon-action="delete" data-id="${p.id}">삭제</button>`:''}${admin&&p.reports?`<small>신고 ${p.reports}건</small>`:''}</div>${p.replies.map(r=>`<div class="anonymous-reply" style="${r.parent_id?'margin-left:20px':''}"><small>${esc(r.author)}${r.parent_id?' · 답글':''}</small><p>${esc(r.body)}</p><button class="auth-link" data-anon-reply="${p.id}" data-parent="${r.id}">답글 달기</button></div>`).join('')}<form class="extra-actions anonymous-reply-form" data-id="${p.id}"><input class="field" name="body" maxlength="1000" placeholder="익명 댓글을 남겨보세요" aria-label="익명 댓글" required><button class="primary">댓글</button></form><p class="board-status" role="status"></p></article>`).join('')||'<section class="panel">아직 글이 없어요. 첫 이야기를 남겨 주세요.</section>'}`;}
 }catch(e){if(location.hash.slice(1)===route)target.innerHTML=`<h1>${esc(titles[route])}</h1><p role="alert">${esc(e.message)}</p>`;}}
function showColorQuestion(){const q=colorGame.questions[colorAnswers.length];document.querySelector('#color-play').innerHTML=`<p class="muted">${colorAnswers.length+1} / 10 · 실제 색을 선택하세요</p><div class="stroop-word" style="color:${q.color}" aria-label="색깔 맞추기 문제">${q.word}</div><div class="stroop-options">${['빨강','파랑','초록','보라'].map((name,i)=>`<button data-color-answer="${i}">${name}</button>`).join('')}</div>`;}
document.addEventListener('click',async e=>{const start=e.target.closest('#color-start'),answer=e.target.closest('[data-color-answer]'),action=e.target.closest('[data-anon-action]'),reply=e.target.closest('[data-anon-reply]');try{
 if(start){start.disabled=true;colorGame=await api('/api/stroop/start',{});colorAnswers=[];showColorQuestion();}
 if(answer&&colorGame){colorAnswers.push(Number(answer.dataset.colorAnswer));if(colorAnswers.length<10)showColorQuestion();else{document.querySelector('#color-play').textContent='기록을 저장하는 중…';const d=await api('/api/stroop/finish',{token:colorGame.token,answers:colorAnswers});colorGame=null;if(location.hash==='#stroop'){await renderExtras('stroop',content);document.querySelector('#color-play').innerHTML=`<h2>${d.correct} / 10 정답</h2><p>${(d.elapsed/1000).toFixed(1)}초 · 오늘 놀이터 보상은 순발력 대결과 합쳐 한 번 지급됩니다.</p><button class="primary" id="color-start">다시 도전하기</button>`;}loadPet();}}
 if(e.target.closest('#anonymous-compose')){const d=extraDialog('익명 글 쓰기',`<form id="anonymous-post-form" class="extra-form"><label>제목<input class="field" name="title" maxlength="120" required></label><label>내용<textarea class="field" name="body" maxlength="5000" required></textarea></label><button class="primary">등록</button><p class="board-status" role="status"></p></form>`);}
 if(action){action.disabled=true;await api('/api/anonymous/'+action.dataset.anonAction,{id:Number(action.dataset.id)});if(action.dataset.anonAction==='report'){action.closest('article').querySelector('.board-status').textContent='신고가 접수되었습니다.';return;}renderExtras('anonymous',content);}
 if(reply){const d=extraDialog('익명 답글',`<form class="anonymous-reply-form extra-form" data-id="${reply.dataset.anonReply}" data-parent="${reply.dataset.parent}"><textarea class="field" name="body" maxlength="1000" required aria-label="답글 내용"></textarea><button class="primary">답글 등록</button><p class="board-status" role="status"></p></form>`);}
 }catch(err){const box=action?.closest('article')?.querySelector('.board-status')||document.querySelector('#color-play');if(box)box.textContent=err.message;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='anonymous-post-form'&&!e.target.matches('.anonymous-reply-form'))return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(f));await api('/api/anonymous/'+(f.id==='anonymous-post-form'?'post':'reply'),{...d,id:Number(f.dataset.id),parent_id:Number(f.dataset.parent||0)});f.closest('dialog')?.close();renderExtras('anonymous',content);}catch(err){f.querySelector('.board-status')?.replaceChildren(document.createTextNode(err.message));b.disabled=false;}});

let studyRestaurants=[],studyUsers=[],studyWeeklyStatus=[],studyWeek='',studyEntries=[];
let studyAvailability=[],studyConfirmations=[];
const studyDayNames=['월','화','수','목','금'];
function studyDayInputs(selected=[]){return `<fieldset class="study-weekdays"><legend>가능한 요일 (여러 날 선택)</legend>${studyDayNames.map((name,i)=>`<label><input type="checkbox" name="days" value="${i}" ${selected.includes(i)?'checked':''}>${name}</label>`).join('')}</fieldset>`;}
function studyAvailabilityMarkup(id){const rows=studyAvailability.filter(x=>x.study_id===id);return rows.length?`<details class="study-participant-details"><summary>참여자 가능한 요일 <span>${rows.length}명</span></summary><div class="study-availability">${rows.map(x=>`<p><span>${esc(x.name)}</span><small>${x.days.length?x.days.map(d=>studyDayNames[d]).join(' · '):'요일 미선택'}</small></p>`).join('')}</div></details>`:'';}
async function showStudyDays(id,action){const data=await studyRequest();studyEntries=data.studys;studyAvailability=data.availability;const target=studyEntries.find(m=>m.id===id);if(!target)return;if(target.kind!=='weekly'){try{await studyRequest('/'+action,{id,...(action==='respond'?{action:'accept'}:{})});await loadStudyInvitations();if(document.querySelector('#study-invitations-dialog')?.open)showStudyInvitations();render();}catch(error){alert(error.message);}return;}let modal=document.querySelector('#study-days-dialog');if(!modal){modal=document.createElement('dialog');modal.id='study-days-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>가능한 공부 요일</h2><button type="button" class="auth-link" data-close>닫기</button></div><form id="study-days-form" data-id="${id}" data-action="${action}" class="board-form">${studyDayInputs(studyAvailability.find(x=>x.study_id===id&&x.user_id===window.hfAuth.user.id)?.days||[])}<button type="submit" class="primary">${action==='availability'?'요일 저장':'요일 선택하고 참여'}</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-close]').onclick=()=>modal.close();const allowed=studyAvailability.find(r=>r.study_id===id&&r.user_id===target.user_id)?.days||[];modal.querySelectorAll('[name=days]').forEach(input=>{if(!allowed.includes(Number(input.value))){input.disabled=true;input.closest('label').hidden=true;}});modal.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('.study-day-edit');if(b)showStudyDays(Number(b.dataset.id),'availability');});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='study-days-form')return;e.preventDefault();const days=new FormData(form).getAll('days').map(Number),button=form.querySelector('[type=submit]');if(!days.length){form.querySelector('.board-status').textContent='가능한 요일을 하나 이상 선택해 주세요.';return;}button.disabled=true;try{await studyRequest('/'+form.dataset.action,{id:Number(form.dataset.id),days,...(form.dataset.action==='respond'?{action:'accept'}:{})});form.closest('dialog').close();await loadStudyInvitations();if(document.querySelector('#study-invitations-dialog')?.open)showStudyInvitations();render();}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
document.addEventListener('click',async e=>{const button=e.target.closest('.study-delete');if(!button)return;if(!confirm('공부 제안을 삭제할까요? 보낸 초대도 함께 삭제됩니다.'))return;button.disabled=true;try{await studyRequest('/remove',{id:Number(button.dataset.id)});await loadStudyInvitations();render();}catch(error){button.disabled=false;const p=document.createElement('p');p.setAttribute('role','alert');p.textContent=error.message;button.after(p);}});
let studyListRefreshing=false;
async function renderSharedStudys(content,refresh=false){
 if(refresh&&studyListRefreshing)return;studyListRefreshing=true;
 if(!refresh)content.innerHTML+=`<div class="study-compose-bar"><div><h2>함께 공부할 사람을 찾아보세요</h2><p>시간과 공부 장소를 정하고, 가능한 요일을 공유해요.</p></div><button type="button" class="primary" id="study-create"><span aria-hidden="true">＋</span> 공부 제안하기</button></div><p class="study-reward-guide">함께 공부하면 하루 10 XP · 처음 함께 공부하는 회원마다 추가 5 XP<br><small>참여자 전원이 완료를 확인하면 반영됩니다. 첫 확인 이후에는 참여자를 변경할 수 없습니다.</small></p><section class="study-proposals" aria-labelledby="study-proposals-title"><div class="study-list-heading"><h2 id="study-proposals-title">제안된 공부</h2><span id="study-count" class="study-count"></span></div><div id="study-list" class="study-proposal-grid" aria-live="polite">공부 제안을 불러오는 중…</div></section>`;
 const list=content.querySelector('#study-list'),count=content.querySelector('#study-count');
 try{const data=await studyRequest();if(!list?.isConnected||list!==content.querySelector('#study-list'))return;studyWeek=data.week;studyEntries=data.studys;studyWeeklyStatus=data.weekly_status||[];studyRestaurants=data.restaurants;studyUsers=data.users;studyAvailability=data.availability||[];studyConfirmations=data.confirmations||[];count.textContent=data.studys.length+'개';const markup=data.studys.length?data.studys.map(m=>{const own=m.user_id===window.hfAuth.user.id,joined=m.members.includes(window.hfAuth.user.id),full=m.members.length>=m.capacity,confirmed=studyConfirmations.filter(c=>c.study_id===m.id),didConfirm=confirmed.some(c=>c.user_id===window.hfAuth.user.id),closed=confirmed.length>0||!!m.finalized_id,allConfirmed=m.members.length>=2&&confirmed.length>=m.members.length;return `<article class="study-card study-card-clean" data-proposal-id="${m.id}"><header class="study-card-heading"><h3>${esc(m.restaurant)}</h3>${m.legacy_body?`<details><summary>기존 제안 내용과 댓글</summary><p>${esc(m.legacy_body)}</p></details>`:''}<span class="study-card-status">${m.finalized_id?'약속 확정':allConfirmed?'공부 확인 완료':closed?'완료 확인 중':m.kind==='weekly'?'주간 모집':full?'모집 마감':'하루 약속'}</span></header><div class="study-card-meta"><p class="study-card-time">${m.kind==='weekly'?esc(m.week)+' 시작 주 · '+(m.slot==='dinner'?'저녁':'낮'):esc(m.event_time.replace('T',' · '))+' · '+(m.slot==='dinner'?'저녁':'낮')}</p><p class="study-card-host">${esc(m.author)}님의 제안 <span>·</span> ${m.members.length} / ${m.capacity}명</p>${m.address?`<p class="study-card-address">${esc(m.address)}</p>`:''}${m.url?`<a class="study-map-link" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">지도에서 위치 보기 ↗</a>`:''}</div>${proposalParticipants(m,studyUsers,'study')}${m.kind==='weekly'?studyAvailabilityMarkup(m.id):''}<div class="study-card-main-actions">${own?`<button type="button" class="primary study-invite-open" data-id="${m.id}" ${closed||full?'disabled':''}>회원 초대하기</button>`:`<button type="button" class="${joined?'auth-link':'primary'} study-join" data-id="${m.id}" ${closed||full&&!joined?'disabled':''}>${joined?'참여 취소':full?'정원 마감':'참여하기'}</button>`}${joined&&m.kind==='weekly'&&!closed?`<button type="button" class="auth-link study-day-edit" data-id="${m.id}">가능 요일 수정</button>`:''}</div>${m.kind!=='weekly'&&(joined||confirmed.length)?`<div class="study-card-complete"><span>${allConfirmed?'✓ 참여자 전원 확인 완료':confirmed.length?`완료 확인 ${confirmed.length} / ${m.members.length}명`:'공부 후 완료를 확인해 주세요'}</span>${joined?`<button type="button" class="study-complete auth-link" data-id="${m.id}" ${didConfirm?'disabled':''}>${didConfirm?'✓ 확인 완료':'공부 완료 확인'}</button>`:''}</div>`:''}${own&&m.kind==='weekly'&&!closed?`<button type="button" class="primary study-finalize" data-id="${m.id}">가능한 날로 약속 확정</button>`:''}${own?`<footer class="study-card-owner"><span>내가 만든 제안</span><button type="button" class="task-delete study-delete" data-id="${m.id}">제안 삭제</button></footer>`:''}</article>`;}).join(''):'<div class="study-empty"><strong>첫 공부를 제안해 보세요</strong><p>등록된 제안이 여기에 표시됩니다.</p></div>';reconcileProposalList(list,markup);}catch(error){if(!refresh&&list?.isConnected)list.textContent=error.message;}finally{studyListRefreshing=false;}
}
async function showStudyInviteForm(id){let modal=document.querySelector('#study-invite-dialog');if(!modal){modal=document.createElement('dialog');modal.id='study-invite-dialog';document.body.append(modal);}const study=studyEntries.find(m=>m.id===id),targetWeek=studyWeekOf(study?.event_time.slice(0,10)||studyCurrentTime().day);let statusRows=[];try{const data=await studyRequest('/weekly?week='+targetWeek);statusRows=data.weekly_status;}catch(error){alert(error.message);return;}const users=studyUsers.filter(u=>u.id!==window.hfAuth.user.id&&!study?.members.includes(u.id));modal.innerHTML=`<div class="progress-dialog-head"><h2>함께 공부할 회원 초대</h2><button type="button" class="auth-link" data-close>닫기</button></div><form id="study-invite-form" data-id="${id}" class="board-form"><p class="muted">초대받은 회원이 수락하면 참여 인원에 포함됩니다.</p><p class="muted">${esc(targetWeek)} 시작 주 · 가능 / 불가 / 미설정 상태를 확인하고 초대하세요.</p><div class="study-member-list">${users.length?users.map(u=>`<label class="study-member"><input type="checkbox" name="recipients" value="${u.id}"><span>${esc(u.name)}${u.department?`<small>${esc(u.department)}</small>`:''}${studyInviteStatus(statusRows.find(r=>r.user_id===u.id))}</span></label>`).join(''):'<p>초대할 승인된 회원이 없습니다.</p>'}</div><button type="submit" class="primary" ${users.length?'':'disabled'}>선택한 회원에게 초대 보내기</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('.study-invite-open');if(b)showStudyInviteForm(Number(b.dataset.id));});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='study-invite-form')return;e.preventDefault();const recipients=new FormData(form).getAll('recipients').map(Number),button=form.querySelector('[type=submit]'),status=form.querySelector('.board-status');if(!recipients.length){status.textContent='초대할 회원을 선택해 주세요.';return;}button.disabled=true;try{await studyRequest('/invite',{id:Number(form.dataset.id),recipients});status.textContent='초대를 보냈습니다. 회원들이 사이트에 접속하면 알림을 받습니다.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
let studyInvitations=[],studyInviteLoading=false;const studyInviteShown=new Set();
async function loadStudyInvitations(){if(studyInviteLoading||!window.hfAuth||document.hidden)return;studyInviteLoading=true;try{const data=await studyRequest('/invitations');studyInvitations=data.invitations;let button=document.querySelector('#study-invitation-button');if(!button){button=document.createElement('button');button.id='study-invitation-button';button.className='auth-link';button.type='button';button.onclick=()=>showStudyInvitations();document.querySelector('.auth-tools')?.append(button);}button.textContent=`공부 초대 ${studyInvitations.length}개`;button.hidden=!studyInvitations.length;if(studyInvitations.some(i=>!studyInviteShown.has(i.id))&&!document.querySelector('dialog[open]'))showStudyInvitations();}catch{}finally{studyInviteLoading=false;}}
function showStudyInvitations(){let modal=document.querySelector('#study-invitations-dialog');if(!modal){modal=document.createElement('dialog');modal.id='study-invitations-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>받은 공부 초대</h2><button type="button" class="auth-link" data-close>닫기</button></div>`+(studyInvitations.length?studyInvitations.map(i=>{studyInviteShown.add(i.id);return `<article class="study-card"><h3>${esc(i.author)}님이 공부에 초대했어요</h3><p>${esc(i.restaurant)} · ${esc(i.event_time.replace('T',' '))}</p><p>${i.members.length} / ${i.capacity}명 참여</p><div class="study-card-actions"><button type="button" class="primary study-invite-respond" data-id="${i.id}" data-action="accept">수락하고 참여</button><button type="button" class="auth-link study-invite-respond" data-id="${i.id}" data-action="decline">거절</button></div><p class="board-status" role="status"></p></article>`;}).join(''):'<p>응답할 초대가 없습니다.</p>');modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
document.addEventListener('click',async e=>{const button=e.target.closest('.study-invite-respond');if(!button)return;if(button.dataset.action==='accept'){showStudyDays(Number(button.dataset.id),'respond');return;}const card=button.closest('article');card.querySelectorAll('button').forEach(b=>b.disabled=true);try{await studyRequest('/respond',{id:Number(button.dataset.id),action:button.dataset.action});await loadStudyInvitations();showStudyInvitations();if(location.hash==='#study')render();}catch(error){card.querySelector('.board-status').textContent=error.message;card.querySelectorAll('button').forEach(b=>b.disabled=false);}});
setInterval(loadStudyInvitations,15000);
function studyCurrentTime(date=new Date()){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return {day:`${p.year}-${p.month}-${p.day}`,time:`${p.hour}:${p.minute}`};}
document.addEventListener('click',async e=>{const button=e.target.closest('#study-map-search');if(!button)return;const form=button.closest('form'),results=form.querySelector('#study-map-results'),query=form.querySelector('[name=restaurant]').value.trim();if(!query){results.textContent='지역과 공부 장소 이름을 입력해 주세요. 예: 문현동 한식';return;}button.disabled=true;results.textContent='카카오 지도에서 검색 중…';try{const data=await studyRequest('/restaurants?q='+encodeURIComponent(query));if(!form.isConnected)return;results.innerHTML=data.places.length?data.places.map((p,i)=>`<button type="button" class="place-result" data-place-index="${i}"><strong>${esc(p.name)}</strong><small>${esc(p.address)}</small></button>`).join(''):'검색 결과가 없습니다. 지역 이름을 함께 입력해 보세요.';results.querySelectorAll('button').forEach(b=>b.onclick=()=>{const p=data.places[Number(b.dataset.placeIndex)];form.querySelector('[name=restaurant]').value=p.name;form.querySelector('[name=address]').value=p.address;form.querySelector('[name=url]').value=p.url;form.querySelector('#study-restaurant-tag').innerHTML=`<span class="restaurant-tag">${esc(p.name)}</span><p class="muted">${esc(p.address)}</p>`;results.innerHTML='';});}catch(error){results.textContent=error.message;}finally{button.disabled=false;}});
async function studyRequest(path='',data){const r=await fetch('/api/studys'+path,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'요청에 실패했습니다.');return result;}
async function renderStudys(content){await renderSharedStudys(content);}
function showStudyForm(){const now=studyCurrentTime();let modal=document.querySelector('#study-dialog');if(!modal){modal=document.createElement('dialog');modal.id='study-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>공부 제안하기</h2><button type="button" class="dialog-close-icon" data-study-close aria-label="닫기"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><form id="study-proposal-form" class="board-form"><label>제안 유형<select class="field" name="kind" id="study-kind"><option value="single">하루 약속</option><option value="weekly">주간 모집</option></select></label><label>공부 구분<select class="field" name="slot"><option value="lunch">낮</option><option value="dinner">저녁</option></select></label><div class="study-datetime" id="study-single-fields"><label>날짜<input class="field" name="study_day" type="date" value="${now.day}" required></label><label>시간<input class="field" name="study_time" type="time" value="${now.time}" step="60" required></label></div><div id="study-weekly-fields" hidden><p class="muted">${esc(studyWeekOf(now.day))} 시작 주 · 가능한 요일을 모은 뒤 제안자가 약속을 확정합니다.</p>${studyDayInputs()}</div><label>정원 (본인 포함)<input class="field" name="capacity" type="number" min="2" max="30" value="4" required></label><label>공부 장소 검색<input class="field" name="restaurant" id="study-restaurant" list="study-restaurants" maxlength="120" required placeholder="공부 장소 이름을 검색하거나 새로 입력하세요"><datalist id="study-restaurants">${studyRestaurants.map(r=>`<option value="${esc(r)}"></option>`).join('')}</datalist></label><button type="button" class="study-search-secondary" id="study-map-search"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg>지도에서 공부 장소 검색</button><div id="study-map-results" aria-live="polite"></div><input type="hidden" name="address"><input type="hidden" name="url"><div id="study-restaurant-tag"></div><button type="submit" class="primary">공부 제안 등록</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-study-close]').onclick=()=>modal.close();modal.querySelector('#study-kind').onchange=()=>{const weekly=modal.querySelector('#study-kind').value==='weekly';modal.querySelector('#study-single-fields').hidden=weekly;modal.querySelector('#study-weekly-fields').hidden=!weekly;modal.querySelectorAll('[name=study_day],[name=study_time]').forEach(i=>{i.disabled=weekly;});modal.querySelectorAll('[name=days]').forEach(i=>i.disabled=!weekly);};modal.querySelector('#study-kind').onchange();modal.querySelector('#study-restaurant').oninput=e=>{modal.querySelector('[name=address]').value='';modal.querySelector('[name=url]').value='';modal.querySelector('#study-restaurant-tag').innerHTML=e.target.value.trim()?`<span class="restaurant-tag">${esc(e.target.value.trim())}</span>`:'';};modal.showModal();}
document.addEventListener('click',async e=>{if(e.target.closest('#study-create')){showStudyForm();return;}const b=e.target.closest('.study-join');if(!b)return;if(b.textContent==='참여하기'){showStudyDays(Number(b.dataset.id),'join');return;}b.disabled=true;try{await studyRequest('/join',{id:Number(b.dataset.id)});render();}catch(error){b.disabled=false;const p=document.createElement('p');p.setAttribute('role','alert');p.textContent=error.message;b.after(p);}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='study-proposal-form')return;e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form)),days=new FormData(form).getAll('days').map(Number);if(data.kind==='weekly'&&!days.length)throw Error('가능한 요일을 하나 이상 선택해 주세요.');await studyRequest('/post',{...data,...(data.kind==='weekly'?{days,week:studyWeekOf(studyCurrentTime().day)}:{}),event_time:data.kind==='single'?data.study_day+'T'+data.study_time:'',capacity:Number(data.capacity)});form.closest('dialog').close();render();}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
