document.addEventListener('click',async e=>{const b=e.target.closest('.study-complete');if(!b)return;b.disabled=true;try{const result=await studyRequest('/complete',{id:Number(b.dataset.id)});await loadActivity();render();showStudyMessage(!result.complete?`완료를 확인했습니다. 현재 ${result.confirmed} / ${result.total}명 확인 중입니다. 참여자 전원이 확인하면 공부 완료와 경험치가 반영됩니다.`:result.earned?`참여자 전원 확인 완료! ${result.earned} XP를 받았습니다.`:'참여자 전원이 공부를 확인했습니다.');}catch(error){b.disabled=false;showStudyMessage(error.message);}});

function studyWeekOf(day){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
