function studyWeeklyForm(){const status=studyWeeklyStatus.find(r=>r.user_id===window.hfAuth.user.id),lunch=status?.lunch||[-1,-1,-1,-1,-1],dinner=status?.dinner||[-1,-1,-1,-1,-1];return `<p class="muted">${esc(studyWeek)} 시작 주 · 초대 화면에 공유됩니다.</p><form id="study-weekly-form" data-week="${esc(studyWeek)}"><div class="study-profile-grid"><span></span><strong>낮</strong><strong>저녁</strong>${studyDayNames.map((name,i)=>`<strong>${name}요일</strong>${studyStatusSelect('lunch',i,lunch[i])}${studyStatusSelect('dinner',i,dinner[i])}`).join('')}</div><p class="muted study-profile-note">매주 새로 설정해 주세요. 이전 주 상태는 다음 주로 복사되지 않습니다.</p><button type="submit" class="primary">내 상태 저장</button><p class="board-status" role="status"></p></form>`;}
async function showStudyProfile(){let modal=document.querySelector('#study-profile-dialog');if(!modal){modal=document.createElement('dialog');modal.id='study-profile-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>${esc(window.hfAuth.user.name)}님의 공부 상태</h2><button type="button" class="auth-link" data-close>닫기</button></div><div id="study-profile-body" aria-live="polite">이번 주 상태를 불러오는 중…</div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();try{const data=await studyRequest('/weekly');studyWeek=data.week;studyWeeklyStatus=data.weekly_status;modal.querySelector('#study-profile-body').innerHTML=studyWeeklyForm();}catch(error){modal.querySelector('#study-profile-body').textContent=error.message;}}
document.addEventListener('click',e=>{if(e.target.closest('.study-profile-open'))showStudyProfile();});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='study-weekly-form')return;e.preventDefault();const b=f.querySelector('button'),d=new FormData(f);b.disabled=true;try{await studyRequest('/weekly',{week:f.dataset.week,lunch:studyDayNames.map((_,i)=>Number(d.get('lunch'+i))),dinner:studyDayNames.map((_,i)=>Number(d.get('dinner'+i)))});const data=await studyRequest('/weekly');studyWeeklyStatus=data.weekly_status;f.querySelector('.board-status').textContent='이번 주 낮·저녁 상태를 저장했습니다.';}catch(error){f.querySelector('.board-status').textContent=error.message;}finally{b.disabled=false;}});
document.addEventListener('click',e=>{const b=e.target.closest('.study-finalize');if(!b)return;const m=studyEntries.find(m=>m.id===Number(b.dataset.id)),rows=studyAvailability.filter(r=>r.study_id===m.id);let modal=document.querySelector('#study-finalize-dialog');if(!modal){modal=document.createElement('dialog');modal.id='study-finalize-dialog';document.body.append(modal);}const options=studyDayNames.map((name,i)=>{const d=new Date(m.week+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);const day=d.toISOString().slice(0,10),available=rows.filter(r=>r.days.includes(i)&&m.members.includes(r.user_id));return {day,name,available};}).filter(x=>x.day>=studyCurrentTime().day&&x.available.length>=2&&x.available.some(r=>r.user_id===m.user_id));modal.innerHTML=`<div class="progress-dialog-head"><h2>주간 모집 약속 확정</h2><button type="button" class="auth-link" data-close>닫기</button></div><form id="study-finalize-form" data-id="${m.id}" class="board-form"><p>선택한 날이 가능한 참여자만 약속에 포함됩니다. ${m.slot==='dinner'?'저녁 18시':'낮 12시'}로 확정됩니다.</p>${options.length?`<label>약속 날짜<select name="day" class="field">${options.map(x=>`<option value="${x.day}">${x.day} (${x.name}) · ${x.available.map(r=>esc(r.name)).join(', ')}</option>`).join('')}</select></label><button class="primary">약속 확정하기</button>`:'<p>제안자를 포함해 두 명 이상 가능한 남은 요일이 없습니다.</p>'}<p class="board-status" role="status"></p></form>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='study-finalize-form')return;e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await studyRequest('/finalize',{id:Number(form.dataset.id),day:new FormData(form).get('day')});form.closest('dialog').close();render();}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
setInterval(()=>{if(location.hash==='#study'&&!document.hidden&&!document.querySelector('dialog[open]')&&!document.activeElement?.closest('form'))renderSharedStudys(content,true);},15000);

const hfRuleTerms=[{"term": "개인", "body": "주택·준주택 수요자, 구상채무자와 주택임대인 등 규정에서 정한 자연인입니다.", "article": "제2조 제1호"}, {"term": "준주택", "body": "이 규정에서는 오피스텔과 노인복지주택을 말합니다.", "article": "제2조 제2의2호"}, {"term": "금융기관", "body": "공사가 보증한 채무의 채권자인 금융기관입니다. 해당 대출을 공사에 양도한 경우 그 대출에 한해 공사를 포함합니다.", "article": "제2조 제3호"}, {"term": "인터넷 보증", "body": "연대보증인 없이 금융기관 홈페이지에서 신청·전자약정·조건변경을 처리하는 보증입니다.", "article": "제2조 제4의2호"}, {"term": "전자약정", "body": "직원과 대면하지 않고 전자서명으로 체결하는 약정입니다.", "article": "제2조 제4의3호"}, {"term": "부분보증", "body": "보증 대상 대출의 책임을 공사와 금융기관이 일정 비율로 나누는 방식입니다.", "article": "제2조 제5호"}, {"term": "보증부대출", "body": "보증조건에 맞게 실행되고 보증효력이 발생한 대출입니다. 공사와 금융기관의 책임분담분을 합한 금액입니다.", "article": "제2조 제6호"}, {"term": "담보부대출", "body": "금융기관이 보증대상 목적물의 담보평가액 범위에서 취급하는 대출입니다.", "article": "제2조 제7호"}, {"term": "당해대출", "body": "보증부대출과 담보부대출을 합한 대출을 뜻합니다.", "article": "제2조 제8호"}, {"term": "보증조건", "body": "보증종류·금액·기한·상대처·피보증인·비율·대상 목적물 등을 정한 공사와 금융기관의 계약사항입니다.", "article": "제2조 제9호"}, {"term": "갱신보증", "body": "기존 보증을 해지하기 위해 그 잔액 이내에서 다시 취급하는 같은 종류의 보증입니다.", "article": "제2조 제10호"}, {"term": "기대출금", "body": "보증서를 발급하기 전에 이미 실행된 대출금입니다.", "article": "제2조 제13호"}, {"term": "동일인", "body": "보증을 신청했거나 이미 이용하고 있는 사람을 뜻합니다.", "article": "제2조 제14호"}, {"term": "집단승인", "body": "요건을 갖춘 사업장에 대해 여러 보증을 취급할 수 있도록 미리 승인하는 절차입니다.", "article": "제2조 제15호"}, {"term": "보증상대처", "body": "기금 출연 금융기관, 별도 계약 금융기관, 해당 대출을 양수한 자 등 보증거래 상대방입니다.", "article": "제3조"}, {"term": "개별보증", "body": "보증부대출 한 건마다 보증서를 발급하는 방식입니다. 분할 실행 예외는 원문 요건을 확인해야 합니다.", "article": "제7조"}];
function renderRuleTerms(q){const box=document.querySelector('#terms');if(!box)return;const source='https://www.hf.go.kr/ko/sub02/sub02_09_01.do?articleNo=600014&mode=view';box.innerHTML=`<p class="muted">HF 공개 개인보증규정의 용어를 쉽게 풀었습니다. 2026.04.28 게시본 · 원문 확인 2026.10.07</p><div class="extra-actions"><a class="auth-link" target="_blank" rel="noopener" href="${source}">개인보증규정 원문 ↗</a><a class="auth-link" target="_blank" rel="noopener" href="https://www.hf.go.kr/ko/sub02/sub02_09_01.do">현행 내규 전체 ↗</a><a class="auth-link" target="_blank" rel="noopener" href="https://alio.go.kr/item/itemOrganList.do?apbaId=C0258&reportFormRootNo=21110">공사 경영내규 ↗</a></div>`+hfRuleTerms.filter(t=>(t.term+' '+t.body).includes(q.trim())).map(t=>`<article class="panel"><h2>${esc(t.term)}</h2><p>${esc(t.body)}</p><small class="muted">개인보증규정 ${esc(t.article)} · <a href="${source}" target="_blank" rel="noopener">근거 확인 ↗</a></small></article>`).join('');}
